class Solution:
    def levelSpreads(self, root):
        level = [] if root is None else [root]
        answer = []
        while level:
            low = high = level[0].val
            next_level = []
            for node in level:
                low = min(low, node.val)
                high = max(high, node.val)
                if node.left is not None:
                    next_level.append(node.left)
                if node.right is not None:
                    next_level.append(node.right)
            answer.append(high - low)
            level = next_level
        return answer

class Solution  {
    public int[] levelSpreads(TreeNode root) {
        if(root==null)return new int[0];
        ArrayDeque<TreeNode> q=new ArrayDeque<>();
        q.add(root);
        ArrayList<Integer>a=new ArrayList<>();
        while(!q.isEmpty()) {
            int size=q.size(),lo=Integer.MAX_VALUE,hi=Integer.MIN_VALUE;
            for(int i=0;i<size;i++) {
                TreeNode n=q.remove();
                lo=Math.min(lo,n.val);
                hi=Math.max(hi,n.val);
                if(n.left!=null)q.add(n.left);
                if(n.right!=null)q.add(n.right);
            }
            a.add(hi-lo);
        }
        return a.stream().mapToInt(Integer::intValue).toArray();
    }
}

class Solution  {
    levelSpreads(root:TreeNode|null):number[] {
        if(!root)return [];
        let level=[root];
        const a:number[]=[];
        while(level.length) {
            a.push(Math.max(...level.map(n=>n.val))-Math.min(...level.map(n=>n.val)));
            const next:TreeNode[]=[];
            for(const n of level) {
                if(n.left)next.push(n.left);
                if(n.right)next.push(n.right);
            }
            level=next;
        }
        return a;
    }
}
